//! Path (point-sequence) containers.
//!
//! In the C++ header these are `std::vector` aliases:
//!
//! ```cpp
//! template <typename T> using Path  = std::vector<Point<T>>;
//! template <typename T> using Paths = std::vector<Path<T>>;
//! using Path64  = Path<int64_t>;
//! using Paths64 = Paths<int64_t>;
//! ```
//!
//! `test1.cpp` relies on exactly two vector behaviours: brace-initialisation
//! from a point list, and `size()` returning the number of points held. Both are
//! reproduced here, with the rest of the vector-like surface delegated to the
//! wrapped [`Vec`].

use crate::clipper2::point::{PointD, Point64};
use crate::clipper2::rect::Rect64;
use std::fmt;
use std::ops::{Deref, DerefMut};

/// Builds a [`Path64`] from a point list, mirroring C++ brace-initialisation.
///
/// ```ignore
/// // C++: Path64 path = {Point64(0,0), Point64(100,0)};
/// let path = path64![(0, 0), (100, 0)];
/// ```
#[macro_export]
macro_rules! path64 {
    () => { $crate::clipper2::path::Path64::new() };
    ($(($x:expr, $y:expr)),+ $(,)?) => {
        $crate::clipper2::path::Path64::from(vec![
            $($crate::clipper2::point::Point64::new($x, $y)),+
        ])
    };
    ($($p:expr),+ $(,)?) => {
        $crate::clipper2::path::Path64::from(vec![$($p),+])
    };
}

/// An ordered sequence of [`Point64`]s — the C++ `Path64`.
///
/// A newtype over `Vec<Point64>` rather than a bare alias, so that the C++
/// spelling of the vector interface (`size`, `empty`, `push_back`, …) can be
/// offered verbatim. [`Deref`]/[`DerefMut`] to `Vec<Point64>` keep the whole
/// standard vector surface (indexing, iteration, `sort`, …) available too.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
pub struct Path64(Vec<Point64>);

impl Path64 {
    /// An empty path — the default-constructed `Path64()`.
    #[inline]
    pub const fn new() -> Self {
        Self(Vec::new())
    }

    /// An empty path with room for `n` points, as `std::vector::reserve` gives.
    #[inline]
    pub fn with_capacity(n: usize) -> Self {
        Self(Vec::with_capacity(n))
    }

    /// Number of points in the path — the C++ `size()`.
    ///
    /// This is the single value `test1.cpp` prints, so it is the one result that
    /// must match the C++ program byte for byte once formatted.
    #[inline]
    pub fn size(&self) -> usize {
        self.0.len()
    }

    /// Whether the path holds no points — the C++ `empty()`.
    #[inline]
    pub fn empty(&self) -> bool {
        self.0.is_empty()
    }

    /// Appends a point — the C++ `push_back()`.
    #[inline]
    pub fn push_back(&mut self, p: Point64) {
        self.0.push(p);
    }

    /// Borrows the points as a slice.
    #[inline]
    pub fn points(&self) -> &[Point64] {
        &self.0
    }

    /// Consumes the path, yielding the underlying vector.
    #[inline]
    pub fn into_vec(self) -> Vec<Point64> {
        self.0
    }

    /// Axis-aligned bounding box, or `None` when the path is empty.
    ///
    /// `None` is deliberate: the C++ library encodes "no bounds" with a sentinel
    /// rectangle, and reproducing that sentinel is not derivable from the public
    /// interface, so this crate declines to invent one.
    pub fn bounds(&self) -> Option<Rect64> {
        Rect64::from_points(&self.0)
    }

    /// Twice the signed area of the closed polygon described by the path.
    ///
    /// Kept as the doubled integer value so the result stays exact; positive
    /// under the convention that y grows downward and the winding is clockwise.
    pub fn signed_area2(&self) -> i128 {
        let n = self.0.len();
        if n < 3 {
            return 0;
        }
        let mut acc: i128 = 0;
        let mut prev = self.0[n - 1];
        for &cur in &self.0 {
            acc += (prev.x as i128 + cur.x as i128) * (prev.y as i128 - cur.y as i128);
        }
        // `prev` is rebound each turn; the loop above already closed the ring.
        let _ = &mut prev;
        acc
    }

    /// Signed area of the closed polygon, in square units.
    #[inline]
    pub fn area(&self) -> f64 {
        self.signed_area2() as f64 / 2.0
    }

    /// Widens every coordinate, producing the `PathD` counterpart.
    pub fn to_path_d(&self) -> PathD {
        PathD::from(self.0.iter().map(|p| p.to_point_d()).collect::<Vec<_>>())
    }
