        let r = Rect64::from_points(&[Point64::new(7, -3)]).expect("non-empty");
        assert_eq!(r, Rect64::new(7, -3, 7, -3));
        assert_eq!((r.width(), r.height()), (0, 0));
        assert!(r.is_empty());
        assert!(r.contains(Point64::new(7, -3)));
    }

    #[test]
