        let r = Rect64::new(0, 0, 100, 100);
        assert_eq!(
            r.corners(),
            [
                Point64::new(0, 0),
                Point64::new(100, 0),
                Point64::new(100, 100),
                Point64::new(0, 100),
            ]
        );
        assert_eq!(r.to_string(), "(0,0,100,100)");
    }
}

