/// Twice the signed area of the closed polygon described by the path.
///
/// The doubled value is returned so the shoelace sum stays exact in integer
/// arithmetic; `i128` accumulation means even full-range `i64` coordinates
/// cannot overflow. Positive when the ring winds clockwise on screen (y
/// growing downward), negative when it winds the other way.
pub fn signed_area2(&self) -> i128 {
    let n = self.0.len();
    if n < 3 {
        return 0;
    }
    let mut acc: i128 = 0;
    let mut prev = self.0[n - 1];
    for &cur in &self.0 {
        acc += prev.x as i128 * cur.y as i128 - cur.x as i128 * prev.y as i128;
        prev = cur;
    }
    acc
}

