/// Twice the signed area of the closed polygon described by the path.
///
/// The doubled value is returned so the shoelace sum stays exact in integer
/// arithmetic. Positive when the ring winds clockwise on screen (y growing
/// downward), negative when it winds the other way.
///
/// Accumulation is in `i128`, which is exact for every coordinate range the
/// C++ library admits. It is *not* wide enough for arbitrary full-range
/// `i64` coordinates — a single cross term can reach `2 * i64::MAX²`, which
/// alone nearly fills an `i128` — so the sum saturates at the `i128` bounds
/// instead of panicking in debug builds and wrapping to a wrong value in
/// release builds.
pub fn signed_area2(&self) -> i128 {
    let n = self.0.len();
    if n < 3 {
        return 0;
    }
    let mut acc: i128 = 0;
    let mut prev = self.0[n - 1];
    for &cur in &self.0 {
        let cross = (prev.x as i128 * cur.y as i128) - (cur.x as i128 * prev.y as i128);
        acc = acc.saturating_add(cross);
        prev = cur;
    }
    acc
}

