//! Axis-aligned rectangle.
//!
//! Mirrors `Clipper2Lib::Rect64`. The field naming follows the C++ header's
//! screen-coordinate convention, in which y grows downward, so `top` is the
//! *smallest* y and `bottom` the largest.

use super::point::Point64;
use std::fmt;

/// An axis-aligned rectangle with 64-bit integer bounds — the C++ `Rect64`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    /// Constructs a rectangle from explicit edges, matching the C++
    /// `Rect64(left, top, right, bottom)` constructor. Edges are stored as
    /// given; no normalisation is applied.
    #[inline]
    pub const fn new(left: i64, top: i64, right: i64, bottom: i64) -> Self {
        Self {
            left,
            top,
            right,
            bottom,
        }
    }

    /// Tightest rectangle covering every point, or `None` for an empty slice.
    ///
    /// `Option` rather than a sentinel rectangle: the C++ library's "invalid
    /// rect" value is an implementation detail that the public interface does
    /// not pin down, so this crate makes the empty case explicit instead.
    pub fn from_points(points: &[Point64]) -> Option<Self> {
        let (first, rest) = points.split_first()?;
        let mut r = Self::new(first.x, first.y, first.x, first.y);
        for p in rest {
            r.left = r.left.min(p.x);
            r.right = r.right.max(p.x);
            r.top = r.top.min(p.y);
            r.bottom = r.bottom.max(p.y);
        }
        Some(r)
    }

    /// Horizontal extent — the C++ `Width()`.
    #[inline]
    pub fn width(&self) -> i64 {
        self.right - self.left
    }

    /// Vertical extent — the C++ `Height()`.
    #[inline]
    pub fn height(&self) -> i64 {
        self.bottom - self.top
    }

    /// Whether the rectangle encloses no area — the C++ `IsEmpty()`.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.bottom <= self.top || self.right <= self.left
    }

    /// Centre point, rounded toward zero by integer division.
    #[inline]
    pub fn mid_point(&self) -> Point64 {
        Point64::new((self.left + self.right) / 2, (self.top + self.bottom) / 2)
    }

    /// Whether `p` lies inside or on the boundary — the C++ `Contains()`.
    #[inline]
    pub fn contains(&self, p: Point64) -> bool {
        p.x >= self.left && p.x <= self.right && p.y >= self.top && p.y <= self.bottom
    }

    /// The four corners, clockwise from the top-left — the C++ `AsPath()`.
    pub fn corners(&self) -> [Point64; 4] {
        [
            Point64::new(self.left, self.top),
            Point64::new(self.right, self.top),
            Point64::new(self.right, self.bottom),
            Point64::new(self.left, self.bottom),
        ]
    }
}

impl fmt::Display for Rect64 {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "({},{},{},{})",
            self.left, self.top, self.right, self.bottom
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bounds_of_the_test1_square() {
        let pts = [
            Point64::new(0, 0),
            Point64::new(100, 0),
            Point64::new(100, 100),
            Point64::new(0, 100),
        ];
        let r = Rect64::from_points(&pts).expect("non-empty");
        assert_eq!(r, Rect64::new(0, 0, 100, 100));
        assert_eq!((r.width(), r.height()), (100, 100));
        assert!(!r.is_empty());
        assert_eq!(r.mid_point(), Point64::new(50, 50));
    }

    #[test]
    fn empty_slice_has_no_bounds() {
        assert_eq!(Rect64::from_points(&[]), None);
    }

    #[test]
    fn single_point_bounds_are_degenerate() {
        let r = Rect64::from_points(&[Point64::new(7, -3)]).expect("non-empty");
        assert_eq!(r, Rect64::new(7, -3, 7, -3));
        assert_eq!((r.width(), r.height()), (0, 0));
        assert!(r.is_empty());
        assert!(r.contains(Point64::new(7, -3)));
    }

    #[test]
    fn negative_coordinates_are_ordered_correctly() {
        let r = Rect64::from_points(&[Point64::new(5, 5), Point64::new(-5, -9)]).unwrap();
        assert_eq!(r, Rect64::new(-5, -9, 5, 5));
        assert!(r.contains(Point64::new(0, 0)));
        assert!(!r.contains(Point64::new(6, 0)));
    }

    #[test]
    fn corners_wind_clockwise_on_screen() {
        let r = Rect64::new(0, 0, 100, 100);
        assert_eq!(
            r.corners(),
            [
                Point64::new(0, 0),
                Point64::new(100, 0),
                Point64::new(100, 100),
                Point64::new(0, 100),
            ]
        );
        assert_eq!(r.to_string(), "(0,0,100,100)");
    }
}

